// ---- 분자 데이터 (좌표 단위: Å). multi: 다중 결합 {"i-j": 차수} ----
function benzene() {
  const atoms = [], multi = {};
  for (let i = 0; i < 6; i++) {
    const a = (i * Math.PI) / 3;
    atoms.push(["C", 1.4 * Math.cos(a), 1.4 * Math.sin(a), 0]);
  }
  for (let i = 0; i < 6; i++) {
    const a = (i * Math.PI) / 3;
    atoms.push(["H", 2.48 * Math.cos(a), 2.48 * Math.sin(a), 0]);
  }
  for (let i = 0; i < 6; i += 2) multi[`${i}-${i + 1}`] = 2;
  return { atoms, multi };
}
function ethane() {
  const atoms = [["C", -0.765, 0, 0], ["C", 0.765, 0, 0]];
  for (let k = 0; k < 3; k++) {
    const a = (k * 2 * Math.PI) / 3, b = a + Math.PI / 3; // 엇갈린 형태
    atoms.push(["H", -1.16, 1.02 * Math.cos(a), 1.02 * Math.sin(a)]);
    atoms.push(["H",  1.16, 1.02 * Math.cos(b), 1.02 * Math.sin(b)]);
  }
  return { atoms, multi: {} };
}
