function latticePoints(basis, n) {
  const out = new Map();
  for (let i = 0; i <= n; i++) for (let j = 0; j <= n; j++) for (let k = 0; k <= n; k++) basis.forEach((b) => {
    const p = [i + b[0], j + b[1], k + b[2]];
    if (p.every((v) => v <= n + 1e-6)) out.set(p.map((v) => v.toFixed(3)).join(), p);
  });
  return [...out.values()];
}
