function covAtoms(m) {
  const out = [], add = (sym, x, y, z) => out.push({ sym, x, y, z, r: ELEMENTS[sym].cov }), a = m.a;
  if (m.struct === "diamond" || m.struct === "quartz") {
    const n = m.struct === "quartz" ? 1 : m.n, si = latticePoints(FCC.concat(FCC.map((p) => p.map((v) => v + .25))), n).map((p) => p.map((v) => v * a));
    si.forEach((p) => add(m.sym, ...p));
    if (m.struct === "quartz") { // 이웃한 Si–Si 사이에 O 하나씩
      const d = a * Math.sqrt(3) / 4;
      for (let i = 0; i < si.length; i++) for (let j = i + 1; j < si.length; j++)
        if (Math.abs(Math.hypot(si[i][0] - si[j][0], si[i][1] - si[j][1], si[i][2] - si[j][2]) - d) < 0.05) add("O", (si[i][0] + si[j][0]) / 2, (si[i][1] + si[j][1]) / 2, (si[i][2] + si[j][2]) / 2);
    }
  } else if (m.struct === "blende") {
    latticePoints(STRUCT.blende.A, m.n).forEach((p) => add(m.cat, p[0] * a, p[1] * a, p[2] * a));
    latticePoints(STRUCT.blende.B, m.n).forEach((p) => add(m.an, p[0] * a, p[1] * a, p[2] * a));
  } else if (m.struct === "c60") {
    const g = (1 + Math.sqrt(5)) / 2, s = m.bond / 2, seen = new Set();
    [[0, 1, 3 * g], [1, 2 + g, 2 * g], [g, 2, 2 * g + 1]].forEach(([x, y, z]) => [1, -1].forEach((sx) => [1, -1].forEach((sy) => [1, -1].forEach((sz) => {
      const p = [x * sx, y * sy, z * sz];
      [p, [p[1], p[2], p[0]], [p[2], p[0], p[1]]].forEach((q) => {
        const key = q.map((v) => v.toFixed(3)).join();
        if (!seen.has(key)) { seen.add(key); add("C", q[0] * s, q[1] * s, q[2] * s); }
      });
    }))));
  } else { // graphite / h-BN
    for (let l = 0; l < m.layers; l++) {
      const basis = !m.cat && l % 2 ? [[0, 0], [2 / 3, 1 / 3]] : [[0, 0], [1 / 3, 2 / 3]];
      for (let i = -4; i <= 4; i++) for (let j = -4; j <= 4; j++) basis.forEach(([u, v], bi) => {
        const x = a * (i + u - (j + v) / 2), y = a * (j + v) * Math.sqrt(3) / 2;
        if (Math.hypot(x, y) <= 5.2) add(m.cat ? ((bi ^ (l % 2)) ? m.an : m.cat) : m.sym, x, y, l * (m.dz || 3.355));
      });
    }
  }
  return out;
}
// 결정 속 입자 좌표(Å, 중심 정렬). box: 단위 정육면체 모양 외곽선 크기
function crystalPoints(m) {
  const S = STRUCT[m.struct], a = m.a, pts = [];
  if (m.kind === "ion") {
    latticePoints(S.A, S.n).forEach((p) => pts.push({ sym: m.cat, role: "cat", x: p[0] * a, y: p[1] * a, z: p[2] * a, r: IONR[m.cat] }));
    latticePoints(S.B, S.n).forEach((p) => pts.push({ sym: m.an, role: "an", x: p[0] * a, y: p[1] * a, z: p[2] * a, r: IONR[m.an] }));
  } else if (m.kind === "cov") {
    covAtoms(m).forEach((p) => pts.push(p));
  } else if (m.struct !== "hcp") {
    latticePoints(S.A, S.n).forEach((p) => pts.push({ sym: m.sym, x: p[0] * a, y: p[1] * a, z: p[2] * a, r: m.r }));
  } else { // 육방 밀집: 육각기둥 단위 격자 (위·아래 층 7개씩 + 가운데 층 3개 = 17개)
    const c = m.c, hx = (k) => [a * Math.cos((k * Math.PI) / 3), a * Math.sin((k * Math.PI) / 3)];
    [0, c].forEach((zz) => {
      pts.push({ sym: m.sym, x: 0, y: 0, z: zz, r: m.r });
      for (let k = 0; k < 6; k++) pts.push({ sym: m.sym, x: hx(k)[0], y: hx(k)[1], z: zz, r: m.r });
    });
    [0, 1, 2].forEach((k) => { const g = Math.PI / 6 + (k * 2 * Math.PI) / 3;
      pts.push({ sym: m.sym, x: (a / Math.sqrt(3)) * Math.cos(g), y: (a / Math.sqrt(3)) * Math.sin(g), z: c / 2, r: m.r }); });
  }
  const lo = [0, 1, 2].map((d) => Math.min(...pts.map((p) => [p.x, p.y, p.z][d]))), hi = [0, 1, 2].map((d) => Math.max(...pts.map((p) => [p.x, p.y, p.z][d])));
  const c = lo.map((v, d) => (v + hi[d]) / 2);
  pts.forEach((p) => { p.x -= c[0]; p.y -= c[1]; p.z -= c[2]; });
  return { pts, box: ["hcp", "graphite", "c60"].includes(m.struct) ? null : hi.map((v, d) => v - lo[d]) };
}

